INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'Token','Unidad básica de texto (palabra, subpalabra o carácter) que los modelos de lenguaje procesan como entrada.',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='Token' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'Transfer Learning','Técnica que aplica conocimiento adquirido en una tarea a otra tarea diferente pero relacionada.',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='Transfer Learning' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'Transformer','Arquitectura de red neuronal basada en mecanismos de atención, fundamento de los modelos de lenguaje modernos',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='Transformer' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'Underfitting (Subajuste)','Situación en que un modelo es demasiado simple para capturar los patrones de los datos, resultando en bajo rendimiento.',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='Underfitting (Subajuste)' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'No supervisado (Aprendizaje no supervisado)','Tipo de aprendizaje donde el modelo descubre patrones en datos sin etiquetas predefinidas',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='No supervisado (Aprendizaje no supervisado)' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'Validación','Proceso de evaluar el rendimiento del modelo usando un conjunto de datos separado del entrenamiento para ajustar hiperparámetros.',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='Validación' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'Variational Autoencoder (VAE)','Modelo generativo que aprende distribuciones de probabilidad sobre los datos para generar nuevas muestras.',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='Variational Autoencoder (VAE)' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'Vector','Representación matemática de datos como una lista de números, fundamental para el procesamiento en modelos de IA',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='Vector' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'Weights (Pesos)','Parámetros numéricos de una red neuronal que determinan la importancia de cada conexión entre neuronas.',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='Weights (Pesos)' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'Word2Vec','Técnica de NLP que convierte palabras en vectores numéricos capturando relaciones semánticas entre términos.',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='Word2Vec' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'XAI (IA Explicable)','Conjunto de métodos y técnicas que hacen que los procesos y decisiones de la IA sean comprensibles para los humanos.',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='XAI (IA Explicable)' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'XGBoost','Algoritmo de gradient boosting de alto rendimiento, muy utilizado en competencias de ciencia de datos y aplicaciones reales',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='XGBoost' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'YOLO (You Only Look Once)','Algoritmo de detección de objetos en tiempo real que analiza imágenes completas en una sola pasada por la red',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='YOLO (You Only Look Once)' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'Zero-shot learning','Capacidad de un modelo para realizar tareas sin haber visto ejemplos de entrenamiento específicos de esas tareas.',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='Zero-shot learning' COLLATE utf8mb4_unicode_ci);
INSERT INTO institucional_glosario (palabra,descripcion,visible) SELECT 'Zero-shot prompting','Técnica de prompting en la que se pide al modelo realizar una tarea sin proporcionarle ejemplos previos.',1 WHERE NOT EXISTS (SELECT 1 FROM institucional_glosario WHERE palabra='Zero-shot prompting' COLLATE utf8mb4_unicode_ci);
